mapper.select:
select user_id, count(*) as count from t_post where user_id in
#{id}
group by user_id

select count(*) from t_post 
where user_id = #{userId} 
and date(create_time) = #{date}

select count(*) from t_post 
where user_id = #{userId} 
and year(create_time) = #{year} 
and month(create_time) = #{month}

select count(*) from t_post 
where user_id = #{userId} 
and JSON_CONTAINS(categories, CONCAT('"', #{category}, '"'))

select COALESCE(SUM(like_count + collect_count), 0) as total
from t_post
where user_id = #{userId}

select p.* from t_post p where p.user_id = #{userId}
and ( p.visibility = 1 or (p.visibility = 2 and exists ( select 1 from t_friend f where (f.user_id = #{currentUserId} and f.friend_id = #{userId}) or (f.user_id = #{userId} and f.friend_id = #{currentUserId}) and f.status = 1 )) )
order by p.create_time desc
